{
 "paper_title": "Some Methods for Classification and Analysis of Multivariate Observations",
 "authors_year": "J. MacQueen, 1967",
 "research_question": "How can an N-dimensional population be partitioned into k sets on the basis of a sample using a computationally feasible process ('k-means'), and what is the asymptotic behavior of this process?",
 "context": "The problem originates from optimal classification structures and optimal information transmission where the expected loss is proportional to squared error. The k-means procedure was devised to find a feasible method of computing such an optimal partition and generalizing ordinary sample means.",
 "methods": [
  "Mathematical analysis using martingale theory to prove asymptotic convergence.",
  "Computer experiments on real and artificial multivariate data using coarsening and refining parameters C and R.",
  "Scrambled dimension tests for independence.",
  "Distance-based classification trees and two-step improvement procedures."
 ],
 "main_findings": [
  "The sequence of random variables W(x^n) converges almost surely to V(x) for some x in the class of unbiased k-points.",
  "The k-means procedure is computationally economical and feasible for large samples on a digital computer.",
  "Empirical tests show the method performs well in similarity grouping, non-linear prediction, distribution approximation, and non-parametric tests of independence."
 ],
 "assumptions": [
  "The probability measure p is absolutely continuous with respect to Lebesgue measure on E^N.",
  "p(R) = 1 for a closed and bounded convex set R subset of E^N, and p(A) > 0 for every open set A subset of R."
 ],
 "limitations_explicit": [
  "In general, the k-means procedure will not converge to an optimal partition, although there are special cases where it will.",
  "So far as the author knows, there is no feasible, general method which always yields an optimal partition."
 ],
 "potential_open_questions": [
  {
   "question": "Can the k-means process be generalized and rigorously proven to converge in general metric spaces under independent sampling beyond specific cases like k=1 and r=1?",
   "why_unresolved": "The extension to general metric spaces faces difficulties regarding the definition of mean and the lack of standard arithmetic operations, leaving the general convergence theorem for metric spaces as a reasonable supposition rather than a complete proof.",
   "evidence": "It would seem reasonable to suppose that the obvious extension of theorem 1 would hold... This is true, at any rate, for k = 1 and r = 1.",
   "sections": [
    "Section 4"
   ]
  }
 ],
 "candidate_hypotheses": [
  {
   "hypothesis": "For fixed marginal distributions, the within-class variance for the optimal partition is maximal when the joint distribution is actually the product of the marginals.",
   "rationale": "Intuition and inspection suggest that scrambling dependent variables to destroy the relationship increases the within-class variance.",
   "evidence": "On the encouraging side is the related conjecture, that for fixed marginal distributions, the within-class variance for the optimal partition as defined in section 1 is maximal when the joint distribution is actually the product of the marginals.",
   "sections": [
    "Section 3.4"
   ]
  }
 ]
}

